/// Brand colours Material 3 has no role for: REC red and success green. Same in every brand option.
@immutable
class TakeTrayColors extends ThemeExtension<TakeTrayColors> {
  const TakeTrayColors({
    required this.recordColor,
    required this.recordOnColor,
    required this.recordColorContainer,
    required this.recordOnColorContainer,
    required this.successColor,
    required this.successOnColor,
    required this.successColorContainer,
    required this.successOnColorContainer,
  });

  final Color recordColor;
  final Color recordOnColor;
  final Color recordColorContainer;
  final Color recordOnColorContainer;
  final Color successColor;
  final Color successOnColor;
  final Color successColorContainer;
  final Color successOnColorContainer;

  static const light = TakeTrayColors(
    recordColor: Color(0xFFCF1D3E),
    recordOnColor: Color(0xFFFFFFFF),
    recordColorContainer: Color(0xFFFFDAD9),
    recordOnColorContainer: Color(0xFF40000B),
    successColor: Color(0xFF196C3B),
    successOnColor: Color(0xFFFFFFFF),
    successColorContainer: Color(0xFFA5F4BB),
    successOnColorContainer: Color(0xFF00210C),
  );
  static const dark = TakeTrayColors(
    recordColor: Color(0xFFFF888C),
    recordOnColor: Color(0xFF680017),
    recordColorContainer: Color(0xFF920025),
    recordOnColorContainer: Color(0xFFFFDAD9),
    successColor: Color(0xFF89D7A0),
    successOnColor: Color(0xFF00391A),
    successColorContainer: Color(0xFF005228),
    successOnColorContainer: Color(0xFFA5F4BB),
  );

  @override
  TakeTrayColors copyWith() => this;

  @override
  TakeTrayColors lerp(TakeTrayColors? other, double t) {
    if (other == null) return this;
    return TakeTrayColors(
      recordColor: Color.lerp(recordColor, other.recordColor, t)!,
      recordOnColor: Color.lerp(recordOnColor, other.recordOnColor, t)!,
      recordColorContainer: Color.lerp(
        recordColorContainer,
        other.recordColorContainer,
        t,
      )!,
      recordOnColorContainer: Color.lerp(
        recordOnColorContainer,
        other.recordOnColorContainer,
        t,
      )!,
      successColor: Color.lerp(successColor, other.successColor, t)!,
      successOnColor: Color.lerp(successOnColor, other.successOnColor, t)!,
      successColorContainer: Color.lerp(
        successColorContainer,
        other.successColorContainer,
        t,
      )!,
      successOnColorContainer: Color.lerp(
        successOnColorContainer,
        other.successOnColorContainer,
        t,
      )!,
    );
  }
}

